<div class="table-responsive po-items-wrapper"><table class="table table-sm align-middle po-items-table"><thead><tr><th style="min-width:280px">Produk katalog</th><th style="min-width:180px">Deskripsi</th><th style="width:95px">Qty</th><th style="width:105px">Satuan</th><th style="width:145px">Harga beli</th><th style="width:48px"></th></tr></thead><tbody data-po-items><?php $items=$po['items']??[[]];foreach($items as $i=>$item): ?><tr data-po-row><td><select name="items[<?= $i ?>][product_id]" class="form-select" data-po-product data-searchable-select data-placeholder="Cari produk..." required><option value=""></option><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>" <?= (int)($item['product_id']??0)===(int)$p['id']?'selected':'' ?>><?= esc(($p['brand']?$p['brand'].' / ':'').$p['name']) ?><?= !empty($p['sku'])?' · '.esc($p['sku']):'' ?></option><?php endforeach; ?></select></td><td><input name="items[<?= $i ?>][description]" class="form-control" value="<?= esc($item['description']??'') ?>"></td><td><input type="number" step="0.01" min="0.01" name="items[<?= $i ?>][quantity]" class="form-control" value="<?= esc($item['quantity']??1) ?>"></td><td><input name="items[<?= $i ?>][unit]" class="form-control" value="<?= esc($item['unit']??'pcs') ?>"></td><td><input type="number" step="0.01" min="0" name="items[<?= $i ?>][unit_price]" class="form-control" value="<?= ($item['unit_price']??'') !== '' && (float)$item['unit_price'] > 0 ? esc($item['unit_price']) : '' ?>" placeholder="Isi harga"></td><td><button type="button" class="btn btn-sm btn-outline-danger" data-po-remove title="Hapus baris"><i class="bi bi-trash3"></i></button></td></tr><?php endforeach; ?></tbody></table></div>
<div class="row g-3 mt-4"><div class="col-12"><h2 class="h6 border-bottom pb-2">Pajak Pembelian</h2></div><div class="col-md-3"><div class="form-check pt-2"><input class="form-check-input" type="checkbox" name="use_ppn" value="1" id="use_ppn" <?= !empty($po['use_ppn'])?'checked':'' ?>><label class="form-check-label" for="use_ppn">Gunakan PPN</label></div></div><div class="col-md-3"><label class="field-label">PPN (%)</label><input type="number" step="0.01" min="0" name="ppn_percent" class="form-control" value="<?= esc($po['ppn_percent']??11) ?>"></div><div class="col-md-3"><div class="form-check pt-2"><input class="form-check-input" type="checkbox" name="use_pph" value="1" id="use_pph" <?= !empty($po['use_pph'])?'checked':'' ?>><label class="form-check-label" for="use_pph">Gunakan PPh</label></div></div><div class="col-md-3"><label class="field-label">PPh (%)</label><input type="number" step="0.01" min="0" name="pph_percent" class="form-control" value="<?= esc($po['pph_percent']??0) ?>"></div><div class="col-12"><label class="field-label">Catatan</label><textarea name="notes" rows="3" class="form-control"><?= esc($po['notes']??'') ?></textarea></div></div></div><div class="card-footer d-flex justify-content-end gap-2"><a href="/purchase-orders" class="btn btn-light">Batal</a><button class="btn btn-primary"><i class="bi bi-save me-1"></i>Simpan PO</button></div></form>
<script>document.addEventListener('DOMContentLoaded',function(){const form=document.querySelector('[data-po-form]');if(!form)return;const body=form.querySelector('[data-po-items]');let nextIndex=body.querySelectorAll('[data-po-row]').length;const products=<?= json_encode(array_map(static fn($p)=>['id'=>$p['id'],'label'=>($p['brand']?$p['brand'].' / ':'').$p['name'].(!empty($p['sku'])?' · '.$p['sku']: '')],$products),JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP) ?>;function initSelects(root){if(window.jQuery&&jQuery.fn.select2)jQuery(root).find('select[data-searchable-select]').each(function(){const s=jQuery(this);if(!s.hasClass('select2-hidden-accessible'))s.select2({theme:'bootstrap-5',width:'100%',placeholder:s.data('placeholder'),allowClear:true,dropdownParent:form});});}function refresh(){const selected=[...body.querySelectorAll('[data-po-product]')].map(s=>s.value).filter(Boolean);body.querySelectorAll('[data-po-product]').forEach(select=>{[...select.options].forEach(option=>{option.disabled=!!option.value&&option.value!==select.value&&selected.includes(option.value);});if(window.jQuery&&jQuery.fn.select2)jQuery(select).trigger('change.select2');});}function makeRow(i){const opts=products.map(p=>`<option value="${p.id}">${p.label}</option>`).join('');return `<tr data-po-row><td><select name="items[${i}][product_id]" class="form-select" data-po-product data-searchable-select data-placeholder="Cari produk..." required><option value=""></option>${opts}</select></td><td><input name="items[${i}][description]" class="form-control"></td><td><input type="number" step="0.01" min="0.01" name="items[${i}][quantity]" class="form-control" value="1"></td><td><input name="items[${i}][unit]" class="form-control" value="pcs"></td><td><input type="number" step="0.01" min="0" name="items[${i}][unit_price]" class="form-control" placeholder="Isi harga"></td><td><button type="button" class="btn btn-sm btn-outline-danger" data-po-remove><i class="bi bi-trash3"></i></button></td></tr>`;}initSelects(form);refresh();form.addEventListener('click',function(e){if(e.target.closest('[data-po-add]')){body.insertAdjacentHTML('beforeend',makeRow(nextIndex++));initSelects(body.lastElementChild);refresh();}if(e.target.closest('[data-po-remove]')){const rows=body.querySelectorAll('[data-po-row]');if(rows.length>1){const select=e.target.closest('[data-po-row]').querySelector('[data-po-product]');if(window.jQuery&&jQuery.fn.select2)jQuery(select).select2('destroy');e.target.closest('[data-po-row]').remove();refresh();}}});form.addEventListener('change',function(e){if(!e.target.matches('[data-po-product]'))return;const value=e.target.value;const duplicate=[...body.querySelectorAll('[data-po-product]')].filter(s=>s.value===value);if(value&&duplicate.length>1){alert('Produk tersebut sudah dipilih pada baris lain.');if(window.jQuery&&jQuery.fn.select2)jQuery(e.target).val(null).trigger('change');else e.target.value='';}refresh();});});</script>
